"""Quiet idle preview: approved eye-only blink and gaze, fixed redrawn hands.
No body movement. Review in isolation; not integrated into app.
"""
from pathlib import Path
from PIL import Image
import numpy as np,io,cairosvg,base64,json
root=Path(__file__).resolve().parents[1];base=Image.open(root/'assets/mascot/spark.png').convert('RGBA');w,h=base.size;Y,X=np.indices((h,w))
edge=np.interp(np.arange(h),[300,310,320,330,340,350,360,370,380,390,400,410,420,430,440,450,460,470,480,490,500],[64,63,62,62,62,62,62,64,65,67,70,73,77,82,87,93,101,110,120,132,145])[:,None]
cut=(Y>=315)&(Y<490)&((X>545-edge)|(X<edge))
svg='''<svg xmlns="http://www.w3.org/2000/svg" width="546" height="546"><defs><linearGradient id="g" x1="0" y1="0" x2=".85" y2="1"><stop stop-color="#e7a064"/><stop offset=".53" stop-color="#c09265"/><stop offset="1" stop-color="#8d9970"/></linearGradient></defs><path d="M480 320 C494 325 508 346 518 368 C530 394 536 417 532 440 C529 463 514 477 497 476 C480 475 469 465 465 448 C460 425 461 394 463 370 C465 345 468 328 480 320 Z" fill="url(#g)" stroke="#5d2c20" stroke-width="10" stroke-linejoin="round" stroke-linecap="round"/><path d="M496 439 C496 454 508 459 516 448" fill="none" stroke="#925a3e" stroke-width="6" stroke-linecap="round"/><path d="M510 363 C516 381 518 397 519 411" fill="none" stroke="#f1ba80" stroke-width="7" stroke-linecap="round" opacity=".65"/></svg>'''
arm=Image.open(io.BytesIO(cairosvg.svg2png(bytestring=svg.encode()))).convert('RGBA');left=arm.transpose(Image.Transpose.FLIP_LEFT_RIGHT)
images=[root/'assets/mascot/spark.png']+[root/f'assets/mascot/blink/blink_{i}.png' for i in (1,2,3)]+[root/f'assets/mascot/look/{side}_{i}.png' for side in ('left','right') for i in (1,2,3)]
frames=[];folder=root/'animation_lab/idle_rest';folder.mkdir(exist_ok=True)
for i,path in enumerate(images):
 img=np.array(Image.open(path).convert('RGBA'));img[:,:,3]=np.where(cut,0,img[:,:,3]);stage=Image.new('RGBA',(806,730));stage.alpha_composite(arm,(130,65));stage.alpha_composite(left,(130,65));stage.alpha_composite(Image.fromarray(img),(130,65));stage.thumbnail((320,314),Image.Resampling.LANCZOS);p=folder/f'frame_{i:02}.png';stage.save(p,optimize=True);frames.append('data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode())
html='''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سبارك في الراحة</title><style>*{box-sizing:border-box}body{margin:0;min-height:100svh;display:grid;place-items:center;padding:20px;background:#fbf6ef;color:#382b26;font-family:system-ui,sans-serif}.card{width:min(100%,460px);background:#fff;border:1px solid #f0e3d6;border-radius:28px;padding:26px;text-align:center;box-shadow:0 12px 35px #8a563315}.badge{display:inline-block;border-radius:99px;background:#fff0e3;color:#b3582d;padding:7px 14px;font-size:13px;font-weight:bold}h1{font-size:24px}p{line-height:1.8;color:#756158}.stage{height:335px;display:grid;place-items:center}img{width:320px;height:314px;object-fit:contain}button{border:0;border-radius:99px;background:#bd603a;color:#fff;font:700 16px system-ui;padding:13px 25px;cursor:pointer}button:focus-visible{outline:3px solid #916541;outline-offset:3px}.note{font-size:13px}</style></head><body><main class="card"><span class="badge">معاينة منفصلة • مش داخل التطبيق</span><h1>سبارك في الراحة 💛</h1><p>واقفة بهدوء، ترمش وتنظر حولها؛ جسمها ورجليها ثابتات.</p><div class="stage"><img id="pet" alt="سبارك واقفة بهدوء، ترمش وتنظر حولها"></div><button id="replay">شغّلي الحركة من جديد ↻</button><p class="note">نفس الرمش والنظر المعتمدين، مع اليدين الجديدتين. تجربة للمراجعة.</p></main><script>const frames=FRAMES;const img=document.getElementById('pet');let timers=[];function run(){timers.forEach(clearTimeout);timers=[];img.src=frames[0];const seq=[[1000,1],[1080,2],[1160,3],[1290,2],[1370,1],[1450,0],[2350,4],[2430,5],[2510,6],[3200,5],[3280,4],[3360,0],[4250,7],[4330,8],[4410,9],[5100,8],[5180,7],[5260,0],[6200,1],[6280,2],[6360,3],[6490,2],[6570,1],[6650,0]];for(const [ms,n] of seq)timers.push(setTimeout(()=>img.src=frames[n],ms));}document.getElementById('replay').onclick=run;if(matchMedia('(prefers-reduced-motion: reduce)').matches)img.src=frames[0];else run();</script></body></html>'''.replace('FRAMES',json.dumps(frames))
(root/'web_extra/spark-idle-rest-preview.html').write_text(html,encoding='utf-8');print('frames',len(frames))
